import { SlashCommandBuilder, PermissionFlagsBits, ChannelType, REST, Routes, InteractionContextType } from 'discord.js';
const admin = (name, description) => new SlashCommandBuilder().setName(name).setDescription(description).setContexts(InteractionContextType.Guild).setDefaultMemberPermissions(PermissionFlagsBits.Administrator);
const period = (s) => s.addStringOption((o) => o.setName('period').setDescription('7d, 14d, 30d, 90d or custom').addChoices(...['7d', '14d', '30d', '90d', 'custom'].map(x => ({ name: x, value: x })))).addStringOption((o) => o.setName('from').setDescription('Custom start date YYYY-MM-DD')).addStringOption((o) => o.setName('to').setDescription('Custom end date YYYY-MM-DD'));
const voice = (o) => o.addChannelOption((x) => x.setName('voice_channel').setDescription('Attendance voice channel').addChannelTypes(ChannelType.GuildVoice, ChannelType.GuildStageVoice).setRequired(true)).addChannelOption((x) => x.setName('voice_channel_2').setDescription('Second voice channel').addChannelTypes(ChannelType.GuildVoice, ChannelType.GuildStageVoice)).addChannelOption((x) => x.setName('voice_channel_3').setDescription('Third voice channel').addChannelTypes(ChannelType.GuildVoice, ChannelType.GuildStageVoice));
const activity = admin('activity', 'Observed activity reports')
    .addSubcommand(s => period(s.setName('user').setDescription('Member report').addUserOption(o => o.setName('member').setDescription('Member').setRequired(true))))
    .addSubcommand(s => period(s.setName('role').setDescription('Current role members').addRoleOption(o => o.setName('role').setDescription('Role').setRequired(true)).addChannelOption(o => o.setName('channel').setDescription('Optional text or voice filter'))))
    .addSubcommand(s => period(s.setName('channel').setDescription('Channel report').addChannelOption(o => o.setName('channel').setDescription('Channel').setRequired(true))))
    .addSubcommand(s => period(s.setName('server').setDescription('Server report')))
    .addSubcommand(s => period(s.setName('game').setDescription('Game report').addStringOption(o => o.setName('game').setDescription('Game name').setRequired(true))))
    .addSubcommand(s => period(s.setName('leaderboard').setDescription('Separate metric ranking').addStringOption(o => o.setName('metric').setDescription('Metric').setRequired(true).addChoices({ name: 'messages', value: 'messages' }, { name: 'voice', value: 'voice' }, { name: 'game', value: 'game' }))))
    .addSubcommand(s => s.setName('inactive').setDescription('No observed qualifying activity').addRoleOption(o => o.setName('role').setDescription('Role').setRequired(true)).addIntegerOption(o => o.setName('days').setDescription('Lookback days').setMinValue(1).setMaxValue(365).setRequired(true)))
    .addSubcommand(s => period(s.setName('compare').setDescription('Current versus previous period')))
    .addSubcommand(s => period(s.setName('export').setDescription('CSV export').addStringOption(o => o.setName('scope').setDescription('Export scope').setRequired(true).addChoices({ name: 'server', value: 'server' }, { name: 'attendance', value: 'attendance' }))))
    .addSubcommand(s => s.setName('health').setDescription('Tracking coverage and configuration'));
const attendance = admin('attendance', 'Discord voice attendance')
    .addSubcommand(s => voice(s.setName('create').setDescription('Preview a new event').addStringOption(o => o.setName('name').setDescription('Event name').setRequired(true)).addStringOption(o => o.setName('start').setDescription('ISO date/time with UTC offset').setRequired(true)).addIntegerOption(o => o.setName('minimum').setDescription('Minimum minutes').setMinValue(0).setRequired(true))).addStringOption((o) => o.setName('end').setDescription('ISO date/time with UTC offset')).addStringOption((o) => o.setName('description').setDescription('Description')))
    .addSubcommand(s => s.setName('update').setDescription('Preview an event change').addIntegerOption(o => o.setName('event').setDescription('Event ID').setRequired(true)).addStringOption(o => o.setName('reason').setDescription('Reason').setRequired(true)).addStringOption(o => o.setName('name').setDescription('New name')).addStringOption(o => o.setName('description').setDescription('New description')).addStringOption(o => o.setName('start').setDescription('New ISO start')).addStringOption(o => o.setName('end').setDescription('New ISO end')).addChannelOption(o => o.setName('voice_channel').setDescription('Replace channels with this voice channel').addChannelTypes(ChannelType.GuildVoice, ChannelType.GuildStageVoice)).addChannelOption(o => o.setName('voice_channel_2').setDescription('Second replacement channel').addChannelTypes(ChannelType.GuildVoice, ChannelType.GuildStageVoice)).addChannelOption(o => o.setName('voice_channel_3').setDescription('Third replacement channel').addChannelTypes(ChannelType.GuildVoice, ChannelType.GuildStageVoice)).addIntegerOption(o => o.setName('minimum').setDescription('Minimum minutes').setMinValue(0)))
    .addSubcommand(s => s.setName('start').setDescription('Start event now').addIntegerOption(o => o.setName('event').setDescription('Event ID').setRequired(true)).addStringOption(o => o.setName('reason').setDescription('Reason').setRequired(true)))
    .addSubcommand(s => s.setName('end').setDescription('End event now').addIntegerOption(o => o.setName('event').setDescription('Event ID').setRequired(true)).addStringOption(o => o.setName('reason').setDescription('Reason').setRequired(true)))
    .addSubcommand(s => s.setName('report').setDescription('Attendance report').addIntegerOption(o => o.setName('event').setDescription('Event ID').setRequired(true)).addUserOption(o => o.setName('member').setDescription('Optional member')).addRoleOption(o => o.setName('role').setDescription('Optional current role')).addBooleanOption(o => o.setName('csv').setDescription('Attach CSV')))
    .addSubcommand(s => s.setName('list').setDescription('Tracked events'))
    .addSubcommand(s => s.setName('history').setDescription('Event setting and correction audit').addIntegerOption(o => o.setName('event').setDescription('Event ID').setRequired(true)))
    .addSubcommand(s => voice(s.setName('import').setDescription('Preview Apollo post import').addStringOption(o => o.setName('apollo_message_url').setDescription('Discord message link').setRequired(true)).addIntegerOption(o => o.setName('minimum').setDescription('Minimum minutes').setRequired(true).setMinValue(0))))
    .addSubcommand(s => s.setName('sync').setDescription('Preview changes from Apollo post').addIntegerOption(o => o.setName('event').setDescription('Event ID').setRequired(true)))
    .addSubcommand(s => s.setName('correct').setDescription('Manual attendance correction').addIntegerOption(o => o.setName('event').setDescription('Event ID').setRequired(true)).addUserOption(o => o.setName('member').setDescription('Member').setRequired(true)).addIntegerOption(o => o.setName('minutes').setDescription('Signed adjustment minutes').setRequired(true)).addStringOption(o => o.setName('reason').setDescription('Reason').setRequired(true)));
const config = admin('activity-config', 'Tracking configuration')
    .addSubcommand(s => s.setName('view').setDescription('View effective settings'))
    .addSubcommand(s => s.setName('set').setDescription('Set a configuration value').addStringOption(o => o.setName('key').setDescription('Setting').setRequired(true).addChoices(...['timezone', 'apolloBotId', 'excludeSelfDeaf', 'requireTwoHumans', 'participationCap', 'retentionDays', 'newcomerGraceDays'].map(x => ({ name: x, value: x })))).addStringOption(o => o.setName('value').setDescription('New value').setRequired(true)))
    .addSubcommand(s => s.setName('add').setDescription('Add excluded channel/category/role or LOA role').addStringOption(o => o.setName('list').setDescription('List').setRequired(true).addChoices(...['excludedChannels', 'excludedCategories', 'excludedRoles', 'loaRoles'].map(x => ({ name: x, value: x })))).addStringOption(o => o.setName('id').setDescription('Discord ID').setRequired(true)))
    .addSubcommand(s => s.setName('remove').setDescription('Remove list entry').addStringOption(o => o.setName('list').setDescription('List').setRequired(true).addChoices(...['excludedChannels', 'excludedCategories', 'excludedRoles', 'loaRoles'].map(x => ({ name: x, value: x })))).addStringOption(o => o.setName('id').setDescription('Discord ID').setRequired(true)))
    .addSubcommand(s => s.setName('alias').setDescription('Set a game alias').addStringOption(o => o.setName('observed').setDescription('Observed game name').setRequired(true)).addStringOption(o => o.setName('canonical').setDescription('Canonical game name').setRequired(true)));
const privacy = admin('activity-data', 'Delete tracked data with confirmation')
    .addSubcommand(s => s.setName('delete-member').setDescription('Delete one member’s stored activity').addUserOption(o => o.setName('member').setDescription('Member').setRequired(true)))
    .addSubcommand(s => s.setName('reset-guild').setDescription('Reset this server’s stored activity'));
export const commands = [activity, attendance, config, privacy];
export async function register(token, clientId, guildId) { const rest = new REST({ version: '10' }).setToken(token); await rest.put(guildId ? Routes.applicationGuildCommands(clientId, guildId) : Routes.applicationCommands(clientId), { body: commands.map(c => c.toJSON()) }); }
